{
  "tilaka": "सिंहव्याघ्रतनुत्राणत्वादिरथविशेषणम् । दन्तादिविकारा दान्तादयस्तत्स्थप्रतिमास्ता धरद्भिरिति शेषः । घोषवत्त्वं किङ्किणीभिः",
  "bhusana": "रूप्येकेत्यादि । पूप्यकोपहितैः रजतनिर्मितैः । कक्ष्याभिः प्रकोष्ठैः. असंहार्यैः अवध्यैः । स्यन्दनयायिभिः स्यन्दनवाहकैः ।। 5.6.4,5।।\n\nसिंहव्याघ्रतनुत्राणैर्दान्तकाञ्चनराजतैः ।\n\nघोषवद्भिर्विचित्रैश्च सदा विचरितं रथैः",
  "siromani": "सिंहव्याघ्राः सिंहव्याघ्रचर्मनिर्मितानि तनुत्राणानि वर्माणि येषु तैः दान्तकाञ्चनराजतीः दन्तादिमयीः प्रतिमाः संधारयद्भिरिति शेषः, घोषवद्भिश्चित्रैः रथैः सदा विचरितं संप्राप्तम्",
  "tattvadipika": "सिंहव्याघ्रतनुत्राणैः तच्चर्मनिर्मितवर्मभिरित्यर्थः"
}
--- 5.6.7 Наполненный множеством драгоценных камней, украшенный превосходными сидениями, Где пребывали великие воины, сражающиеся на колесницах, где были великолепные колесницы.
{
  "tilaka": "महतां रथानामावापः स्थानं समन्ताद्यस्मिंस्तत् । महरथानाम् \"एको दशसहस्राणि योधयेद्यस्तु धन्विनाम् । शस्त्रशास्त्रप्रवीणश्च स महारथ उच्यते ।।\" इत्युक्तलक्षणमहारथानां महासनं सदा वासस्थानम्",
  "bhusana": "बहुरत्नसमाकीर्णं परार्घ्यासनभाजनम् ।\n\nमहारथसमावासं महारथमहास्वनम्",
  "siromani": "बहुरत्नसमाकीर्णं परार्ध्यासनैर्भूषितं महारथानाम् \"एको दशसहस्राणि योधयेद्यस्तु धन्विनाम् । शस्त्रशास्त्रप्रवीणश्च स महारथ उच्यते\" इत्यादावुक्तानां समावापः सदा स्थितिर्यस्मिन् अत एव महारथानां महासनानि यस्मिन् तत्",
  "tattvadipika": "महारथसमावासं महारथानां रथिकविशेषणां समावासं स्थानम् । समावापमिति पाठे ऽप्ययमेवार्थः । महारथं च तत् महासनं च महारथमहासनम्"
}
--- 5.6.8 Наполненный повсюду привлекательными для взора, прекрасными Многими тысячами зверей и птиц.
{
  "bhusana": "दृश्यैश्च परमोदारैस्तैस्तैश्च मृगपक्षिभिः ।\n\nविविधैर्बहुसाहस्रैः परिपूर्णं समन्ततः",
  "tattvadipika": "दृश्यैः दर्शनीयैः । परमोदारैः अतिमहद्भिः । \"उदारो दातृमहतोः\" इत्यमरः"
}
--- 5.6.9 Обученными стражами и ракшасами хорошо охраняемый, Полный повсюду прекрасными женщинами.
{
  "tilaka": "अन्तपालैः पर्यन्तरक्षकैः",
  "bhusana": "विनीतैरन्तपालैश्च रक्षोभिश्च सुरक्षितम् ।\n\nमुख्याभिश्च वरस्त्रीभिः परिपूर्णं समन्ततः",
  "siromani": "विनीतैः अन्तपालैर्बहिः स्थित्या रक्षकैः रक्षोभिः सुरक्षितं मुख्याभिः प्रधानाभिर्वरस्त्रीभिः परिपूर्णम्",
  "tattvadipika": "अन्तपालैः बाह्यरक्षकैः"
}

--- 5.6.10 Дворец владыки ракшасов с радостными женщинами-жемчужинами, [Оглашаемый] бряцанием великолепных украшений, звучал подобно океану.
{
  "bhusana": "मुदितप्रमदारत्नं राक्षसेन्द्रनिवेशनम् ।\n\nवराभरणसंह्रादैः समुद्रस्वननिस्वनम्",
  "siromani": "मुदितानि प्रमदारत्नानि श्रेष्ठप्रमदा यस्मिन् तत् राक्षसेन्द्राणां निवेशनं प्रवेशो यस्मिन् वराभरणसंह्रादैः उत्तमभूषणनिःस्वनैः समुद्रस्वनसदृशः निस्वनो यस्मिन् तत्"
}
--- 5.6.11 Наделенный [всем тем], что достойно царского сана, с великолепным сандалом, Был полон [дворец] великими людьми, словно лесная чаща – львами.
{
  "tilaka": "तद्राजगुणसंपन्नं तैः प्रसिद्धै राजभवनगुणैः छत्रचामरादिभिः संपन्नम् । वरचन्दनैश्च संपन्नमित्यनुकर्षः",
  "bhusana": "अन्तपालैः बाह्यरक्षिभिः । राक्षसेन्द्रनिवेशननं राक्षसेन्द्रा राक्षसश्रेष्ठाः निविशन्ते समीपे निवसन्त्यस्मिन्निति राक्षसेन्द्रनिवेशनमित्यर्थः । अन्यथा वक्ष्यमाणवेश्मपदेन पुनरुक्तिः स्यात् । संहादः शब्दः । समुद्रस्वनवन्निस्वनतीति समुद्रस्वननिस्वनम् । पचाद्यच् ।। 5.6.9,10।।\n\nतद्राजगुणसंपन्नं मुख्यैश्चागुरुचन्दनैः ।\n\nमहाजनैः समाकीर्णं सिंहैरिव महद्वनम्",
  "siromani": "तद्राजगुणसंपन्नं तैः प्रसिद्धैः राजगुणैः राजकीयपदार्थैः संपन्नं युक्तं वरचन्दनैश्च संपन्नमिति शेषः, सिंहैर्महद्वनमिव महाजनसमाकीर्णम्"
}
--- 5.6.12 Оглашаемый низкими звуками барабанов и тамбуринов, оглашаемый пением раковин, В котором неизменно в дни изменения луны совершались жертвоприношения, всегда почитаемый ракшасами,
{
  "tilaka": "पर्वसु सुतः सोमो यस्मिन्यज्ञार्थे तत्पर्वसुतम् । राक्षसैः सदा पूजितं स्वपूजनीयदेवताकम्",
  "bhusana": "भेरीमृदङ्गाभिरुतं शङ्खघोषनिनादितम् ।\n\nनित्यार्चितं पर्वहुतं पूजितं राक्षसैः सदा",
  "siromani": "भेरीमृदङ्गैः अभिरुतं शब्दितं पर्वसु सुतं सोमसवनं यस्मिन् तत् राक्षसैः पूजितं कृतसंमार्जनादिकम्"
}
--- 5.6.13 Был глубоким, подобно океану, и звучал, словно океан. Огромный дворец великого духом, покрытый (украшенный) огромными драгоценными камнями,
{
  "bhusana": "समुद्रमिव निःस्वनं निःशब्दम्, रावणभीत्या जनकोलाहलरहितमित्यर्थः । समुद्रस्वननिस्वनमिति तु बाह्यकक्ष्यापेक्षया ।। 5.6.13,14।।\n\nचचार हनुमांस्तत्र रावणस्य समीपतः",
  "siromani": "समुद्रमिव गम्भीरं महारत्नानि महारत्नमयाः परिच्छदाः अलङ्कारादयो यस्मिन्"
}
--- 5.6.14 Полный огромных драгоценных камней увидела великая обезьяна, Сияющий своим внешним видом, полный слонов, коней и колесниц,
{
  "bhusana": "विराजमानं वपुषा गजाश्वरथसङ्कुलम् ।\n\nलङ्काभरणमित्येव सो ऽमन्यत महाकपिः",
  "siromani": "महात्मनो रावणस्य वपुषा विराजमानं महत् विशालं महात्मनो वेश्म गृहं महाकपिर्हनुमान् ददर्श । दशानामेकत्रान्वयः"
}
--- 5.6.16 От дома к дому ракшасов и сады все Оглядывая и дома, шел он, бесстрашный.
{
  "tilaka": "गृहाद्गृहं राजवेश्म । महाप्राकारान्तर्वर्ति प्रधानरक्षसामेकस्य गृहादपरं गृहमित्यर्थः",
  "bhusana": "गृहाद् गृहं राक्षसानामुद्यानानि च वानरः ।\n\nवीक्षमाणो ह्यसंत्रस्तः प्रासादांश्च चचार सः",
  "siromani": "गृहादिति । राक्षसानां गृहात् गृहं गृहान्तरं सर्वशः उद्यानानि च प्रासादांश्च वीक्षमाणः असंत्रस्तः संत्रासरहितः हनूमान् चचार"
}

--- 5.6.29 Спящих рядом с Раваной (охраняющих покои Раваны) увидел лучший из обезьян, Расхаживая [там], тигр среди обезьян, ракшаси с уродливыми (злобными) глазами.
{
  "tilaka": "उपशायिन्यः । \"उपशायोपशायश्च पर्यायशयनार्थकाः\" । पर्यायेण शयनस्थानरक्षिका इत्यर्थ इत्याहुः",
  "bhusana": "रावणस्योपशायिन्यो ददर्श हरिसत्तमः ।\n\nविचरन् हरिशार्दूलो राक्षसीर्विकृतेक्षणाः ।\n\nशूलमुद्गरहस्ताश्च शक्तितोमरधारिणीः\nरावणस्येति । उपशायिन्यः पर्यायशायनीः । रावणे शयाने जाग्रतीरित्यर्थः ।। 5.6.29,30।।\n\nरक्तान् श्वेतान् सितांश्चैव हरींश्चापि महाजवान् ।\n\nकुलीनान् रूपसम्पन्नान् गजान् परगजारुजान्",
  "siromani": "रावणस्येति । रावणस्य उपशायिन्यः उपशायिनीः समीपशयनशीलाः पर्यङ्करक्षिका इत्यर्थः, राक्षसीः हरिसत्तमः हरयः सत्तमाः यस्य सः बहुमहावानराधीश इत्यर्थः, हरिशार्दूलो ददर्श",
  "tattvadipika": "उपशायिन्यः समीपशायिन्यः"
}
--- 5.6.30 С копьями и боевыми молотами в руках, носящих трезубцы и дротики, Увидел [Хануман] разнообразные отряды во дворце владыки ракшасов.
{
  "tilaka": "गुल्मान्राक्षसीसमूहान्",
  "bhusana": "ददर्श विविधान् गुल्मांस्तस्य रक्षःपतेर्गृहे ।\n\nराक्षसांश्च महाकायान्नानाप्रहरणोद्यतान्",
  "siromani": "शूलेति । रक्षः पतेर्गृहे गुल्मान्राक्षसीसमूहान्ददर्श",
  "tattvadipika": "ददर्शेति । गुल्मान् सेनाः । \"गुल्मो रुक्स्तम्बसेनासु\" इत्यमरः"
}
--- 5.6.32 Породистых прекрасных слонов, уничтожителей вражеских слонов, Специально обученных, в битве подобных [слону Индры] Айравате,
{
  "tilaka": "परगजारुजाञ्शत्रुगजानारुजन्ति भञ्जयन्ति तान् ।। 5.6.32,33 ।।\n\nमेघस्तनितनिर्घोषत्वादिविशिष्टान्गजान्ददर्शेत्यन्वयः । सहस्रं वाहिनीरनेकसेनाः",
  "bhusana": "निष्ठितान् गजशिक्षायामैरावतसमान् युधि ।\n\nनिहन्तृ़न् परसैन्यानां गहे तस्मिन् ददर्श सः"
}
--- 5.6.33 Уничтожителей вражеских войск в том доме увидел он, Источающие [маду], они были подобны облакам или горам, струящим потоки,
{
  "bhusana": "क्षरतश्च यथा मेघान् स्रवतश्च यथा गिरीन् ।\n\nमेघस्तनितनिर्घोषान् दुर्धर्षान् समरे परैः"
}
--- 5.6.34 Голоса их были подобны грому, они были непобедимы в бою для противников. Там тысячи воинских отрядов (или повозок), украшенных золотом,
{
  "bhusana": "सहस्रं वाहिनीस्तत्र जाम्बूनदपरिष्कृताः ।\n\nहेमजालपरिच्छन्नास्तरुणादित्यसन्निभाः\nसहस्रमिति । वाहिनीः सेनाः, पदातीनित्यर्थः । जाम्बूनदं जम्बूनदीप्रभवं स्वर्णम् । हेम केवलस्वर्णम्, उभयविधस्वर्णमयाभरणयुक्ता इत्यर्थः ।। 5.6.34,35।।\n\nशिबिका विविधाकाराः स कपिर्मारुतात्मजः ।\n\nलतागृहाणि चित्राणि चित्रशाला गृहाणि च",
  "siromani": "सहस्रमिति । जाम्बूनदपरिष्कृताः सुवर्णभूषिताः सहस्रं बह्वीः वाहिनीः सेनाः हेमजालैरपि छन्नाः सर्वतो भूषिता इत्यर्थः, तरुणादित्यसंनिभाः विविधाकाराः शिबिकाश्च रावणस्य निवेशने कपिर्ददर्श । अर्धचतुष्टयमेकान्वयि ।। 5.6.34,35 ।।\n\nलतेति । चित्राणि लतागृहाणि चित्रशालागृहाणि विचित्रशालारूपवेश्मानि च दारुनिर्मिताः पर्वताः येषु तानि क्रीडागृहाणि च कामस्य गृहकं रतिवेश्म दिवागृहकं दिवसविहारगृहं च रावणस्य निवेशने ददर्श । अर्धचतुष्टयमेकान्वयि ।। 5.6.36,37।।\n\nस इति । स हनूमान् मन्दरतलप्रख्यं मन्दराचलतलसदृशं मयूरस्थानैः क्रीडाहेतुकमयूरस्थितिभिः संकुलं व्याप्तं ध्वजयष्टिभिराकीर्णं व्याप्तं भवनोत्तमं ददर्श"
}
--- 5.6.39 С множеством знамен на древках увидел лучший из дворцов, С грудами драгоценных камней и сокровищ повсюду, Которые были обретены [Раваной] стойким подвижничеством, который был подобен дворцу Владыки земли (Шивы).
{
  "bhusana": "अनेकरत्नसङ्कीर्णं निधिजालं समन्तत ।\n\nधीरनिष्ठितकर्मान्तं गृहं भूतपतेरिव",
  "siromani": "अनन्तेति । अनन्तरत्नानां निचयो यस्मिन् निधिजालं निधिसमूहविशिष्टं धीरैः निष्ठितम् अनुष्ठितकर्माङ्गं निधिरक्षकक्रियावयवो यस्मिन् भूतपतेर्बह्मणः गृहमिव गृहसदृशं रत्नानाम् अर्चिर्भिः रावणस्य तेजसा च उपलक्षितं तद्वेश्म रश्मिभिः किरणैः रश्मिमान् सूर्य इव विरराज । श्लोकद्वयमेकान्वयि ।। 5.6.39,40 ।।\n\nजाम्बूनदेति । जाम्बूनदमयानि शयनादीनि ददर्श"
}
--- 5.6.42 Во влажный от сладкого вина, полный чашами, украшенными жемчугом, Пленительный, просторный, словно дворец Куберы,
{
  "tilaka": "मध्वासवयोरवान्तरभेदस्ताभ्यां कृतक्लेदम् आर्द्रमित्यर्थः",
  "bhusana": "अर्चिर्भिरिति । रश्मिमान् सूर्यः ।। 5.6.40,41।।\n\nमध्वासवकृतक्लेदं मणिभाजनसङ्कुलम् ।\n\nमनोरममसम्बाधं कुबेरभवनं यथा ।\n\nनूपुराणां च घोषेण काञ्चीनां निनदेन च",
  "tattvadipika": "मध्विति । मध्वासवकृतक्लेदं मध्वासवैः क्षौद्रविकारमद्यैः कृतद्रवम्"
}

--- 5.6.15 «Вот украшение Ланки», - подумала великая обезьяна. Ходил Хануман там рядом с [дворцом] Раваны.
{
  "siromani": "सीतान्वेषणमेव वर्णयन्नाह स इत्यादिभिः । लाघवेनातिवेगेन समन्वितः कपिर्हनूमान् विमानेषु सप्तभूमिकप्रासादेषु विचरन् सन् निकामं यथेच्छं लङ्कां विचचार\nपरमोदारैः अतिमहद्भिः अत एव दृश्यैर्विविधैः अनेकप्रकारैः तैस्तैः प्रसिद्धैः बहुसाहस्रैः मृगपक्षिभिः परिपूर्णम्\nलङ्केति । तत्र तस्मिन्समये हनुमान् इतीदं गृहं लङ्काभरणममन्यत रावणस्य समीपतो रावणभवनसमीपे चचार च",
  "tilaka": "दृश्यैर्दर्शनीयः अत एव परमोदारैरतिसुन्दरैः\nपरिच्छदो ऽलङ्कारः । महात्मनो रावणस्य महद्वेश्म ददर्शेत्यन्वयः ।। 5.6.13,14 ।।\n\nअमन्यत तद्रावणवेश्मेति शेषः । रावणस्य रावणभवनस्य समीपतस्तत्प्राकारप्रदेशेषु",
  "bhusana": "तत् प्रसिद्धम् । राजगुणसंपन्नं राजोपचारैर्धूपादिभिः संपन्नम् । अगुरुचन्दनैरित्यत्रापि संपन्नमिति संबध्यते । पर्वसु हुतं होमो यस्मिन् तत् पर्वहुतम् ।। 5.6.11,12 ।।\n\nसमुद्रमिव गम्भीरं समुद्रमिव निःस्वनम् ।\n\nमहात्मनो महद्वेश्म महारत्नपरिच्छदम् ।\n\nमहारत्नसमाकीर्णं ददर्श स महाकपिः\nस इत्यादि । मयूरस्थानं क्रीडामयूरविश्रमस्थानम् । कपोतानामिव मयूराणामपि स्थानानि शिलाभिः कल्प्यन्त इति प्रसिद्धम् । धीरनिष्ठितकर्मान्तं धीरैः कृतकल्पकर्मकम् । भूतपतेः प्रमथाधिपस्य ।। 5.6.38,39।।\n\nअर्चिर्भिश्चापि रत्नानां तेजसा रावणस्य च ।\n\nविरराजाथ तद्वेश्म रश्मिमानिव रश्मिभिः"
}
--- 5.6.17 Полетев (прыгнув), стремительный, к дому Прахасты, Затем отважный (Хануман) направился к дому Махапаршвы.
{
  "tilaka": "राक्षसेन्द्राणां महापार्श्वादीनां निवेशनानि यस्मिंस्तत् । भूषणशब्दैः समुद्रस्वनसदृशनिःस्वनम्",
  "bhusana": "अवप्लुत्य महावेगः प्रहस्तस्य निवेशनम् ।\n\nततो ऽन्यत् पुप्लुवे वेश्म महापार्श्वस्य वीर्यवान् ।। 4.6.17।।\n\nअथ मेघप्रतीकाशं कुम्भकर्णनिवेशनम् ।\n\nविभीषणस्य च तदा पुप्लुवे स महाकपिः",
  "siromani": "अवप्लुत्येति । महावेगो हनूमान् प्रहस्तस्य तदभिधराक्षसस्य निवेशनं गृहमवप्लुत्य ततो ऽन्यत् महापार्श्वस्य वेश्म पुप्लुवे"
}
--- 5.6.20 И Вайджадамштры направилась великая обезьяна, И Шуки и мудрого Сараны [посетил] стремительный [Хануман].
{
  "bhusana": "शुकस्य च महातेषाः सारणस्य च धीमतः ।\n\nतथा चेन्द्रजितो वेश्म जगाम हरियूथपः",
  "siromani": "शुकस्येति । इन्द्रजितः मेघनादस्य वेश्म जगाम"
}
--- 5.6.21 Затем к дому Индраджита направился предводитель обезьяньих стай, [Затем] пошел лучший из обезьян к [домам] Джамбумали и Сумали,
{
  "bhusana": "जम्बुमालेः सुमालेश्च जगाम हरिसत्तमः ।\n\nरश्मिकेतोश्च भवनं सूर्यशत्रोस्तथैव च",
  "siromani": "जाम्बुमालेरिति । अर्धं पृथक्"
}
--- 5.6.28 Обойдя дома их всех со всех сторон, Достиг наделенный удачей [Хануман] дворца владыки ракшасов.
{
  "bhusana": "सर्वेषां समतिक्रम्य भवनानि समन्ततः ।\n\nआससादाथ लक्ष्मीवान् राक्षसेन्द्रनिवेशनम्",
  "siromani": "सर्वेषामिति । सर्वेषां भवनानि समतिक्रम्य अथ पुनः राक्षसेन्द्रनिवेशनमाससाद"
}
--- 5.6.35 Покрытых позолотой, сияющих, словно молодое солнце, Увидела во дворце Раваны, владыки ракшасов,
{
  "tilaka": "हेमजालैरविच्छिन्नाः सर्वतो भूषिता इति शिबिकाविशेषणम्",
  "bhusana": "ददर्श राक्षसेन्द्रस्य रावणस्य निवेशने"
}
--- 5.6.36 Различные видом паланкины та обезьяна – сын ветра. Увитые лианами беседки и прекрасные картинные залы,
{
  "tilaka": "शिबिका ददर्शेत्यनुकर्षः । चित्रशालागृहाणि चित्रयुक्तशालावन्ति गृहाणि"
}
--- 5.6.37 Залы для игр и иные, и деревянные горки, И домик для любовных игр, и прекрасный домик для дневных дел,
{
  "tilaka": "दारुनिर्मिताः क्रीडापर्वता दारुपर्वतकानि क्लीबत्वमार्षम् । कामस्य गृहकं रतिगृहकम् दिवागृहकं दिनविहारगृहम् सर्वत्रात्यन्तस्वार्थिकः कन्",
  "bhusana": "क्रीडागृहाणि चान्यानि दारुपर्वतकानपि ।\n\nकामस्य गृहकं रम्यं दिवागृहकमेव च ।\n\nददर्श राक्षसेन्द्रस्य रावणस्य निवेशने"
}
--- 5.6.38 Увидел [Хануман] во дворце Раваны, владыки ракшасов. Подобный горе Мандаре, полный насестов (мест) для павлинов,
{
  "tilaka": "मयूरस्थानैः क्रीडामयूरस्थानैः सङ्कुलं व्याप्तम्",
  "bhusana": "स मन्दरगिरिप्रख्यं मयूरस्थानसङ्कुलम् ।\n\nध्वजयष्टिभिराकीर्णं ददर्श भवनोत्तमम्"
}
--- 5.6.41 Сделанные из золота ложа и сидения, И великолепные чаши увидел вождь обезьяньих стай.
